use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl Annotatable { # [doc = " Returns the `Span` (source code location) of the annotatable item."] # [doc = ""] # [doc = " For n00bs: The `Span` tells you exactly where in your original code"] # [doc = " this piece of the AST came from. It's like a bookmark for the compiler."] pub fn span (& self) -> Span { match self { Annotatable :: Item (item) => item . span , Annotatable :: AssocItem (assoc_item , _) => assoc_item . span , Annotatable :: ForeignItem (foreign_item) => foreign_item . span , Annotatable :: Stmt (stmt) => stmt . span , Annotatable :: Expr (expr) => expr . span , Annotatable :: Ty (ty) => ty . span , Annotatable :: Pat (pat) => pat . span , Annotatable :: Arm (arm) => arm . span , Annotatable :: ExprField (field) => field . span , Annotatable :: PatField (fp) => fp . pat . span , Annotatable :: GenericParam (gp) => gp . ident . span , Annotatable :: Param (p) => p . span , Annotatable :: FieldDef (sf) => sf . span , Annotatable :: Variant (v) => v . span , Annotatable :: WherePredicate (wp) => wp . span , Annotatable :: Crate (c) => c . spans . inner_span , } } # [doc = " Visits the attributes associated with this annotatable item."] # [doc = ""] # [doc = " This method allows you to apply a function `f` to the `AttrVec` (list of attributes)"] # [doc = " of the underlying AST node."] # [doc = ""] # [doc = " For n00bs: If you have a `#[derive(Debug)]` on a struct, this method lets you"] # [doc = " access that `#[derive(Debug)]` part and do something with it."] pub fn visit_attrs (& mut self , f : impl FnOnce (& mut AttrVec)) { match self { Annotatable :: Item (item) => item . visit_attrs (f) , Annotatable :: AssocItem (assoc_item , _) => assoc_item . visit_attrs (f) , Annotatable :: ForeignItem (foreign_item) => foreign_item . visit_attrs (f) , Annotatable :: Stmt (stmt) => stmt . visit_attrs (f) , Annotatable :: Expr (expr) => expr . visit_attrs (f) , Annotatable :: Ty (ty) => ty . visit_attrs (f) , Annotatable :: Pat (pat) => pat . visit_attrs (f) , Annotatable :: Arm (arm) => arm . visit_attrs (f) , Annotatable :: ExprField (field) => field . visit_attrs (f) , Annotatable :: PatField (fp) => fp . visit_attrs (f) , Annotatable :: GenericParam (gp) => gp . visit_attrs (f) , Annotatable :: Param (p) => p . visit_attrs (f) , Annotatable :: FieldDef (sf) => sf . visit_attrs (f) , Annotatable :: Variant (v) => v . visit_attrs (f) , Annotatable :: WherePredicate (wp) => wp . visit_attrs (f) , Annotatable :: Crate (c) => c . visit_attrs (f) , } } # [doc = " Allows a visitor to traverse the annotatable item."] # [doc = ""] # [doc = " This is part of the AST traversal mechanism, letting `Visitor` implementations"] # [doc = " inspect the structure of the AST."] # [doc = ""] # [doc = " For n00bs: If you want to look through all the parts of your Rust code in a structured way,"] # [doc = " a \"visitor\" can walk this AST tree. This method lets the visitor step into this"] # [doc = " particular `Annotatable` part."] pub fn visit_with < 'a , V : Visitor < 'a > > (& 'a self , visitor : & mut V) -> V :: Result { match self { Annotatable :: Item (item) => visitor . visit_item (item) , Annotatable :: AssocItem (item , ctxt) => visitor . visit_assoc_item (item , * ctxt) , Annotatable :: ForeignItem (foreign_item) => visitor . visit_foreign_item (foreign_item) , Annotatable :: Stmt (stmt) => visitor . visit_stmt (stmt) , Annotatable :: Expr (expr) => visitor . visit_expr (expr) , Annotatable :: Ty (ty) => visitor . visit_ty (ty) , Annotatable :: Pat (pat) => visitor . visit_pat (pat) , Annotatable :: Arm (arm) => visitor . visit_arm (arm) , Annotatable :: ExprField (field) => visitor . visit_expr_field (field) , Annotatable :: PatField (fp) => visitor . visit_pat_field (fp) , Annotatable :: GenericParam (gp) => visitor . visit_generic_param (gp) , Annotatable :: Param (p) => visitor . visit_param (p) , Annotatable :: FieldDef (sf) => visitor . visit_field_def (sf) , Annotatable :: Variant (v) => visitor . visit_variant (v) , Annotatable :: WherePredicate (wp) => visitor . visit_where_predicate (wp) , Annotatable :: Crate (c) => visitor . visit_crate (c) , } } # [doc = " Converts the annotatable item into a `TokenStream`."] # [doc = ""] # [doc = " This is typically used when a macro needs to generate new code or"] # [doc = " transform existing code represented as a `TokenStream`."] # [doc = ""] # [doc = " For n00bs: After a macro has done its work changing the AST, it often needs"] # [doc = " to turn that changed AST back into actual Rust code text that the compiler"] # [doc = " can understand. This method helps do that conversion."] pub fn to_tokens (& self) -> TokenStream { match self { Annotatable :: Item (node) => TokenStream :: from_ast (node) , Annotatable :: AssocItem (node , _) => TokenStream :: from_ast (node) , Annotatable :: ForeignItem (node) => TokenStream :: from_ast (node) , Annotatable :: Stmt (node) => { assert ! (! matches ! (node . kind , ast :: StmtKind :: Empty)) ; TokenStream :: from_ast (node) } Annotatable :: Expr (node) => TokenStream :: from_ast (node) , Annotatable :: Ty (node) => TokenStream :: from_ast (node) , Annotatable :: Pat (node) => TokenStream :: from_ast (node) , Annotatable :: Arm (..) | Annotatable :: ExprField (..) | Annotatable :: PatField (..) | Annotatable :: GenericParam (..) | Annotatable :: Param (..) | Annotatable :: FieldDef (..) | Annotatable :: Variant (..) | Annotatable :: WherePredicate (..) | Annotatable :: Crate (..) => panic ! ("unexpected annotatable") , } } # [doc = " Tries to unwrap the `Annotatable` into a `Box<ast::Item>`, panicking if it's another type."] pub fn expect_item (self) -> Box < ast :: Item > { match self { Annotatable :: Item (i) => i , _ => panic ! ("expected Item") , } } # [doc = " Tries to unwrap the `Annotatable` into a `Box<ast::AssocItem>` (trait item), panicking if it's another type."] pub fn expect_assoc_item (self) -> Box < ast :: AssocItem > { match self { Annotatable :: AssocItem (i , _) => i , _ => panic ! ("expected Associated Item") , } } # [doc = " Tries to unwrap the `Annotatable` into a `Box<ast::ForeignItem>`, panicking if it's another type."] pub fn expect_foreign_item (self) -> Box < ast :: ForeignItem > { match self { Annotatable :: ForeignItem (i) => i , _ => panic ! ("expected foreign item") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::Stmt`, panicking if it's another type."] pub fn expect_stmt (self) -> ast :: Stmt { match self { Annotatable :: Stmt (stmt) => * stmt , _ => panic ! ("expected statement") , } } # [doc = " Tries to unwrap the `Annotatable` into a `Box<ast::Expr>`, panicking if it's another type."] pub fn expect_expr (self) -> Box < ast :: Expr > { match self { Annotatable :: Expr (expr) => expr , _ => panic ! ("expected expression") , } } # [doc = " Tries to unwrap the `Annotatable` into a `Box<ast::Ty>`, panicking if it's another type."] pub fn expect_ty (self) -> Box < ast :: Ty > { match self { Annotatable :: Ty (ty) => ty , _ => panic ! ("expected type") , } } # [doc = " Tries to unwrap the `Annotatable` into a `Box<ast::Pat>`, panicking if it's another type."] pub fn expect_pat (self) -> Box < ast :: Pat > { match self { Annotatable :: Pat (pat) => pat , _ => panic ! ("expected pattern") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::Arm`, panicking if it's another type."] pub fn expect_arm (self) -> ast :: Arm { match self { Annotatable :: Arm (arm) => arm , _ => panic ! ("expected match arm") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::ExprField`, panicking if it's another type."] pub fn expect_expr_field (self) -> ast :: ExprField { match self { Annotatable :: ExprField (field) => field , _ => panic ! ("expected field") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::PatField`, panicking if it's another type."] pub fn expect_pat_field (self) -> ast :: PatField { match self { Annotatable :: PatField (fp) => fp , _ => panic ! ("expected field pattern") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::GenericParam`, panicking if it's another type."] pub fn expect_generic_param (self) -> ast :: GenericParam { match self { Annotatable :: GenericParam (gp) => gp , _ => panic ! ("expected generic parameter") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::Param`, panicking if it's another type."] pub fn expect_param (self) -> ast :: Param { match self { Annotatable :: Param (param) => param , _ => panic ! ("expected parameter") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::FieldDef`, panicking if it's another type."] pub fn expect_field_def (self) -> ast :: FieldDef { match self { Annotatable :: FieldDef (sf) => sf , _ => panic ! ("expected struct field") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::Variant`, panicking if it's another type."] pub fn expect_variant (self) -> ast :: Variant { match self { Annotatable :: Variant (v) => v , _ => panic ! ("expected variant") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::WherePredicate`, panicking if it's another type."] pub fn expect_where_predicate (self) -> ast :: WherePredicate { match self { Annotatable :: WherePredicate (wp) => wp , _ => panic ! ("expected where predicate") , } } # [doc = " Tries to unwrap the `Annotatable` into an `ast::Crate`, panicking if it's another type."] pub fn expect_crate (self) -> ast :: Crate { match self { Annotatable :: Crate (krate) => krate , _ => panic ! ("expected krate") , } } }
}